-- Fictional class/guest Marketing Lab fixtures, entirely rolled back.
RESET ROLE;
DELETE FROM firstten_private.guest_admission_buckets WHERE bucket_hash=encode(sha256(convert_to('global-guest-entry','UTF8')),'hex');
CREATE TABLE firstten_policy_test.gm_results(label text PRIMARY KEY,result jsonb);
CREATE TABLE firstten_policy_test.gm_docs(label text PRIMARY KEY,document jsonb);
GRANT SELECT,INSERT,UPDATE ON firstten_policy_test.gm_results TO authenticated,service_role;
GRANT SELECT ON firstten_policy_test.gm_docs TO authenticated,service_role;
