aved","revision":"Explain the save step"}}],"outreach":[{"id":"fc230000-0000-4000-8000-000000000103","channelId":"fc230000-0000-4000-8000-000000000101","recipientRole":"Club organizer","purpose":"permission","subject":"May we invite relevant builders?","body":"We are building a prototype. Could we share a small optional activity? END_OF_OUTREACH_DRAFT","respectfulExit":"No problem if this does not fit your group.","status":"draft","observation":"Not sent"}],"resources":{"cashBudgetCents":0,"availableMinutes":60,"existingResources":"Classroom and existing prototype","limitations":"No promotional budget","fallback":"Paper worksheet"},"test":{"hypothesis":"Three relevant learners will try one interview script in a week","state":"draft","primaryMetric":"useful_action","baseline":null,"target":null,"unknowns":"","measurementPlan":"","repeatIf":"","reviseIf":"","stopIf":"","startOn":null,"endOn":null,"reviewOn":null,"tasks":[{"id":"fc230000-0000-4000-8000-000000000104","title":"Check organizer permission","ownerAlias":"Team A","dueOn":null,"prerequisite":"Read club rules","doneMeans":"Permission recorded","status":"todo","completionNote":"Not done"}]},"measurements":[{"id":"fc230000-0000-4000-8000-000000000105","channelId":"fc230000-0000-4000-8000-000000000101","assetId":"fc230000-0000-4000-8000-000000000102","metric":"useful_action","cohort":"peer_test","from":"2026-10-18","to":"2026-10-18","unit":"unique_people","count":null,"source":"No real test performed","recordedOn":"2026-10-18","limitations":"Fictional fixture; unknown is not zero"}],"reflection":{"decision":"revise","evidenceIds":["fc230000-0000-4000-8000-000000000105"],"learned":"No demand established by this fictional example","uncertainty":"Audience fit remains unknown","nextAction":"Ask permission and recruit relevant people"}}');
CREATE FUNCTION firstten_policy_test.gm_session(label text)RETURNS text LANGUAGE sql STABLE AS $$SELECT result->>'sessionToken'FROM firstten_policy_test.gm_results WHERE gm_results.label=$1$$;
CREATE FUNCTION firstten_policy_test.gm_doc()RETURNS jsonb LANGUAGE sql STABLE AS $$SELECT document FROM firstten_policy_test.gm_docs WHERE label='full'$$;
GRANT EXECUTE ON FUNCTION firstten_policy_test.gm_session(text),firstten_policy_test.gm_doc()TO authenticated,service_role;
SELECT ok(NOT has_table_privilege('anon','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'anonymous has no raw guest marketing grants');
SELECT ok(NOT has_table_privilege('authenticated','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'account identity gains no private guest plan access');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.guest_marketing_plans','SELECT,INSERT,UPDATE,DELETE'),'service role uses fixed RPC only');
SELECT ok(NOT has_table_privilege('service_role','firstten_private.guest_marketing_operations','SELECT,INSERT,UPDATE,DELETE'),'save receipts are closed');
SELECT ok(NOT has_function_privilege('anon','public.load_guest_marketing_plan(text,uuid)','EXECUTE'),'anonymous direct RPC denied');
SELECT ok(NOT has_function_privilege('authenticated','public.save_guest_marketing_plan(text,uuid,text,bigint,uuid,boolean,jsonb)','EXECUTE'),'account bearer cannot impersonate guest');
SELECT ok(NOT has_function_privilege('service_role','firstten_private.normalize_guest_marketing(jsonb)','EXECUTE'),'private helper is closed');
SELECT firstten_policy_test.set_actor('owner_a');SET LOCAL ROLE authenticated;
SELECT is(public.create_class('fc230000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('name','Fictional marketing workshop','mode','class','instructions','Fictional QA only','accessExpiresAt',clock_timestamp()+interval '20 days','retentionDays',30))->>'ok','true','create actual class for manual lab');
INSERT INTO firstten_policy_test.gm_results SELECT 'entry',public.create_guest_entry('fc230000-0000-4000-8000-000000000001',7,2,gen_random_uuid());
RESET ROLE;SET LOCAL ROLE service_role;
INSERT INTO firstten_policy_test.gm_results SELECT 'a',public.exchange_guest_entry('entry',(SELECT result->>'token'FROM firstten_policy_test.gm_results WHERE label='entry'),'Fictional marketing A','Fictional learner A',repeat('9',64));
INSERT INTO firstten_policy_test.gm_results SELECT 'other',public.exchange_guest_entry('entry',(SELECT result->>'token'FROM firstten_policy_test.gm_results WHERE label='entry'),'Fictional marketing B','Fictional learner B',repeat('9',64));
INSERT INTO firstten_policy_test.gm_results SELECT 'buddy',public.exchange_guest_entry('team_invite',(SELECT result#>>'{secrets,teamInvite}'FROM firstten_policy_test.gm_results WHERE label='a'),'','Fictional teammate',repeat('9',64));
SELECT is((SELECT result->>'ok'FROM firstten_policy_test.gm_results WHERE label='a'),'true','real principal enters without account');
SELECT is((SELECT result->>'ok'FROM firstten_policy_test.gm_results WHERE label='buddy'),'true','real teammate enters distinct principal');
SELECT is(public.list_guest_marketing_plans(firstten_policy_test.gm_session('a'))#>'{data}','[]'::jsonb,'new learner has no auto-copied private plan');
SELECT is(public.load_guest_marketing_plan(repeat('a',64),'fc230000-0000-4000-8000-000000000011')->>'code','NOT_FOUND','forged session denied');
INSERT INTO firstten_policy_test.gm_results SELECT 'save',public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',0,'fc230000-0000-4000-8000-000000000031',false,firstten_policy_test.gm_doc());
SELECT is((SELECT result->>'ok'FROM firstten_policy_test.gm_results WHERE label='save'),'true','save genuine principal-private manual lab');
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011')#>'{data,document}',firstten_policy_test.gm_doc(),'reload exact content/outreach/test/measurement/reflection');
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000011')->>'code','NOT_FOUND','teammate cannot read private plan');
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('other'),'fc230000-0000-4000-8000-000000000011')->>'code','NOT_FOUND','other team cannot read private plan');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'code','NOT_FOUND','teammate cannot edit private plan');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','team_shared',1,gen_random_uuid(),true,firstten_policy_test.gm_doc())->>'code','NOT_FOUND','existing private plan cannot be relabeled shared');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000012','team_shared',0,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'code','INVALID_INPUT','explicit shared audience confirmation required');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000012','team_shared',0,gen_random_uuid(),true,firstten_policy_test.gm_doc())->>'ok','true','create explicitly authored shared business plan');
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000012')->>'ok','true','teammate may read shared plan');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000012','team_shared',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{title}','"A teammate revision"'))->>'ok','true','teammate edits shared plan with CAS');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000012','team_shared',1,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'code','CONFLICT','stale teammate write cannot overwrite shared plan');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{thinking,observations}','"Rewrite first attempt"'))->>'code','PRESERVED_VERSION','preserved first thinking immutable');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{resources,cashBudgetCents}','1'))->>'code','INVALID_INPUT','cash budget stays zero');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,firstten_policy_test.gm_doc()||'{"user_id":"fc230000-0000-4000-8000-000000000099"}')->>'code','INVALID_INPUT','account identity cannot be added to closed document');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{content,0,channelId}','"fc230000-0000-4000-8000-000000000099"'))->>'code','INVALID_INPUT','foreign channel reference rejected');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{measurements,0,from}','"2026-10-19"'))->>'code','INVALID_INPUT','reversed measurement window rejected');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',1,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{channels,0,name}',to_jsonb(repeat('😀',120))))->>'ok','true','Unicode bounds count code points consistently');
INSERT INTO firstten_policy_test.gm_results SELECT 'replay',public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',0,'fc230000-0000-4000-8000-000000000031',false,firstten_policy_test.gm_doc());
SELECT is((SELECT result#>>'{data,replayed}'FROM firstten_policy_test.gm_results WHERE label='replay'),'true','exact uncertain retry returns original receipt');
SELECT is((SELECT result#>>'{data,savedRevision}'FROM firstten_policy_test.gm_results WHERE label='replay'),'1','receipt preserves original acknowledged revision');
SELECT is((SELECT result#>>'{data,record,revision}'FROM firstten_policy_test.gm_results WHERE label='replay'),'2','replay returns newer current record separately');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',0,'fc230000-0000-4000-8000-000000000031',false,jsonb_set(firstten_policy_test.gm_doc(),'{title}','"Changed retry"'))->>'code','IDEMPOTENCY_CONFLICT','stable mutation cannot change payload');
-- Explicit workspace caps are independent of the operation-receipt cap.
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000013','principal_private',0,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'ok','true','second private plan allowed');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000014','principal_private',0,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'ok','true','third private plan allowed');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000015','principal_private',0,gen_random_uuid(),false,firstten_policy_test.gm_doc())->>'code','CAPACITY','fourth private plan denied without replacing saved work');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),('fc230000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'team_shared',0,gen_random_uuid(),true,firstten_policy_test.gm_doc())->>'ok','true','shared plans two through five allowed')FROM generate_series(20,23)n;
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000024','team_shared',0,gen_random_uuid(),true,firstten_policy_test.gm_doc())->>'code','CAPACITY','shared cap is per team across different principals');
SELECT 'GUEST_MARKETING_DTO:'||jsonb_build_object('save',(SELECT result FROM firstten_policy_test.gm_results WHERE label='save'),'replay',(SELECT result FROM firstten_policy_test.gm_results WHERE label='replay'),'load',public.load_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011'),'list',public.list_guest_marketing_plans(firstten_policy_test.gm_session('a')),'denied',public.load_guest_marketing_plan(firstten_policy_test.gm_session('buddy'),'fc230000-0000-4000-8000-000000000011'))::text;
RESET ROLE;
INSERT INTO firstten_private.guest_marketing_operations(principal_id,request_id,payload_hash,target_id,saved_revision)SELECT(SELECT(result#>>'{data,principalId}')::uuid FROM firstten_policy_test.gm_results WHERE label='a'),gen_random_uuid(),repeat('a',64),'fc230000-0000-4000-8000-000000000011',1 FROM generate_series(1,2000-(SELECT count(*)FROM firstten_private.guest_marketing_operations WHERE principal_id=(SELECT(result#>>'{data,principalId}')::uuid FROM firstten_policy_test.gm_results WHERE label='a')));
SET LOCAL ROLE service_role;
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',2,gen_random_uuid(),false,jsonb_set(firstten_policy_test.gm_doc(),'{title}','"Capacity attempt"'))->>'code','CAPACITY','ordinary intent history bounded');
SELECT is(public.save_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011','principal_private',0,'fc230000-0000-4000-8000-000000000031',false,firstten_policy_test.gm_doc())->>'ok','true','exact retry remains available at cap without new receipts');
INSERT INTO firstten_policy_test.gm_results SELECT 'recovered',public.exchange_guest_entry('principal_recovery',(SELECT result#>>'{secrets,principalRecovery}'FROM firstten_policy_test.gm_results WHERE label='a'),'','',repeat('9',64));
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('a'),'fc230000-0000-4000-8000-000000000011')->>'code','NOT_FOUND','principal recovery invalidates old browser session');
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('recovered'),'fc230000-0000-4000-8000-000000000011')->>'ok','true','recovery returns same private plan');
RESET ROLE;
UPDATE public.classes SET archived_at=clock_timestamp(),revision=revision+1 WHERE id='fc230000-0000-4000-8000-000000000001';
SET LOCAL ROLE service_role;
SELECT is(public.load_guest_marketing_plan(firstten_policy_test.gm_session('recovered'),'fc230000-0000-4000-8000-000000000011')->>'code','NOT_FOUND','closed class denies private export acquisition');
SELECT is(public.list_guest_marketing_plans(firstten_policy_test.gm_session('buddy'))->>'code','NOT_FOUND','closed class denies shared listings');
RESET ROLE;
SELECT ok(NOT EXISTS(SELECT 1 FROM public.class_guest_principals p JOIN auth.users u ON u.id=p.id WHERE p.class_id='fc230000-0000-4000-8000-000000000001'),'manual marketing creates no fake auth identities');
SELECT ok((SELECT count(*)=8 FROM firstten_private.guest_marketing_plans WHERE class_id='fc230000-0000-4000-8000-000000000001'),'only the eight deliberately created private/shared plans exist');
